// M12D — per-requirement overrides. These are the rows where the family-level
// profile would be WRONG, and getting them right is the whole point of doing a
// real mapping pass rather than painting a family green.
//
// Two kinds of override live here:
//   * NARROWING  — the family has evidence but THIS member does not. Honest
//                  status UNVERIFIED or DEFERRED/DECISION, never CODE.
//   * SHARPENING — this member has BETTER evidence than its family (usually a
//                  named proof), so it gets a specific citation.
import { A, T, L, D } from './rules.mjs';

const U = (why, impl = '—') => ['UNVERIFIED', impl, '—', '—', 'D', why];
const DEC = (why) => ['DECISION', '—', '—', '—', 'C', why];
const DEF = (why) => ['DEFERRED', '—', '—', '—', 'C', why];
const NA = (why) => ['NA', '—', '—', '—', 'C', why];

